function Counters() {
  let plainCount = 0;
  const [stateCount, setStateCount] = useState(0);

  function handleClick() {
    plainCount = plainCount + 1;
    setStateCount(stateCount + 1);
    console.log("plainCount:", plainCount, "| stateCount (this render):", stateCount);
  }

  return (
